const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.woff2':'font/woff2','.svg':'image/svg+xml','.png':'image/png'};
const server=http.createServer(async(req,res)=>{try{const u=new URL(req.url,'http://localhost'),file=path.resolve(dist,u.pathname==='/'?'index.html':'.'+u.pathname.replace(/^\/assets/,''));if(!file.startsWith(dist+path.sep)){res.writeHead(403).end();return;}res.setHeader('Content-Type',types[path.extname(file)]||'application/octet-stream');res.end(await fs.readFile(file));}catch{res.writeHead(404).end();}});
(async()=>{await fs.mkdir(out,{recursive:true});await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',resolve);});base='http://127.0.0.1:'+server.address().port;
 try{browser=await chromium.launch({channel:'chrome',headless:true});const context=await browser.newContext({acceptDownloads:true,viewport:{width:1440,height:1000},reducedMotion:'reduce'}),page=await context.newPage();page.setDefaultTimeout(10000);page.on('pageerror',e=>report.errors.push(e.message));page.on('download',d=>report.downloads.push(d.suggestedFilename()));
 await context.route('**/*',async route=>{const r=route.request(),u=new URL(r.url());if(u.origin!==base){report.external_requests.push(u.origin);return route.abort();}if(r.method()!=='GET'){report.writes.push(u.pathname);return route.abort();}if(!u.pathname.startsWith('/api/'))return route.continue();const p=u.pathname.slice(4);let body;
  if(p==='/obligations/export'){
   report.queries.push(Object.fromEntries(u.searchParams));const selected=mode;
   if(selected==='delay')await new Promise(resolve=>{release=resolve;});
   if(selected==='error')return route.fulfill({status:500,json:{detail:'Export temporarily unavailable.'}});
   if(selected==='expired')return route.fulfill({status:401,json:{detail:'Session expired. Please sign in.'}});
   if(selected==='json')return route.fulfill({json:{detail:'Unexpected JSON'}});
   const format=u.searchParams.get('format'),file=await fs.readFile(path.join(fixtures,'example.'+format));
   try{return await route.fulfill({contentType:format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv; charset=utf-8',headers:{'Content-Disposition':'attachment; filename="obligations-example.'+format+'"'},body:file});}catch(error){if(selected!=='delay')throw error;return;}
  }
  if(p==='/auth/me')body=identity;else if(p==='/masters')body=masters;else if(p==='/tasks'||p==='/notifications')body=[];else if(p==='/auth/demo-users')body={users:[]};else if(p==='/obligations')body={items:[obligation],pagination};else if(p==='/obligations/example')body=detail;else if(['/applicability','/accountability'].includes(p))body={items:[],pagination:{...pagination,total:0,start:0,end:0},summary:p==='/applicability'?{assessments:0,partial:0,exclusions:0,unassessed:0}:{awaiting:0,accepted:0,objected:0,missing:0},counts:p==='/applicability'?{obligations:0,records:0,assessments:0,unassessed:0}:{obligations:0,records:0,assignments:0,missing:0}};else throw Error('Unexpected read '+p);
  await route.fulfill({json:body});
 });
 const open=async hash=>{await page.goto(base+'/?exportqa='+(++sequence)+'#'+hash);await page.locator('.obligation-workspace-tabs,.obligation-detail,.access-boundary').first().waitFor();};
 const dialog=()=>page.locator('#dialog');
 const start=async()=>{await page.getByRole('button',{name:'Export',exact:true}).click();await dialog().getByRole('heading',{name:'Export obligations',exact:true}).waitFor();};
 const choose=async format=>{await dialog().locator('select[name=format]').selectOption(format,{force:true});};
 const download=async format=>{const pending=page.waitForEvent('download');await dialog().getByRole('button',{name:'Download',exact:true}).click();const file=await pending;assert.equal(file.suggestedFilename(),'obligations-example.'+format);const saved=path.join(out,'download-'+report.downloads.length+'.'+format);await file.saveAs(saved);assert.deepEqual(await fs.readFile(saved),await fs.readFile(path.join(fixtures,'example.'+format)));await page.waitForFunction(()=>!document.querySelector('#dialog').open);};
 await open('obligations?q=customer&department=retail&tab=reports&page.register=9&size.register=10');
 await page.locator('#view-filter [name=q]').fill('unapplied change');await start();assert.equal(await dialog().locator('select[name=format]').inputValue(),'xlsx');assert(await dialog().getByText('Register · Exceptions',{exact:true}).isVisible());assert(await dialog().getByText('Excel includes grouped applicability and accountability reports',{exact:false}).isVisible());await page.screenshot({path:path.join(out,'export-desktop.png')});await download('xlsx');assert.deepEqual(report.queries.at(-1),{q:'customer',department:'retail',tab:'reports',view:'register',format:'xlsx'});report.checks.push('Excel is the default. Register explains the grouped/flat sheets, uses applied filters across all pages, excludes paging/unapplied edits and downloads exact serializer-generated bytes.');
 await start();await choose('csv');await download('csv');report.checks.push('CSV format downloads exact UTF-8 bytes with the filename supplied by the API.');
 for(const view of ['applicability','accountability']){const query=view==='applicability'?'assessment=NOT_APPLICABLE&gap=1&legal_entity=bank':'role=BUSINESS&response=ACCEPT&owner=person&mine=1&history=1';await open('obligations?view='+view+'&q=customer&department=retail&'+query+'&page.'+view+'=2&size.'+view+'=10');await start();assert(await dialog().getByText('Excel opens on a Grouped report',{exact:false}).isVisible());assert.equal(await dialog().getByText('Accountability also merges repeated departments, with one row per owner.',{exact:false}).count(),view==='accountability'?1:0);assert.equal(await dialog().getByText('Applicability also merges repeated departments, with one row per assessment.',{exact:false}).count(),view==='applicability'?1:0);await download('xlsx');await start();await choose('csv');await download('csv');assert.equal(report.queries.at(-1).view,view);assert(!Object.keys(report.queries.at(-1)).some(k=>k.startsWith('page')||k.startsWith('size')));for(const [k,v]of new URLSearchParams(query))assert.equal(report.queries.at(-1)[k],v);}
 report.checks.push('Applicability and Accountability download both formats with focused filters. Both views explain repeated-department merges while retaining separate assessment or owner rows.');
 await open('obligations/example?tab=owners');await page.getByRole('button',{name:'Export obligation',exact:true}).click();await download('xlsx');assert.deepEqual(report.queries.at(-1),{view:'register',obligation_id:'example',format:'xlsx'});report.checks.push('Full obligation exports the exact selected revision and its related details without inheriting list filters.');
 await open('obligations');await start();mode='error';let before=report.downloads.length;await dialog().getByRole('button',{name:'Download',exact:true}).click();await dialog().getByRole('alert').filter({hasText:'Export temporarily unavailable.'}).waitFor();assert.equal(report.downloads.length,before);mode='ok';await download('xlsx');report.checks.push('API failure remains in the modal with a usable retry; no error page is downloaded.');
 await start();mode='json';await dialog().getByRole('button',{name:'Download',exact:true}).click();await dialog().getByRole('alert').filter({hasText:'did not return an export file'}).waitFor();assert.equal(report.downloads.length,before+1);await page.keyboard.press('Escape');report.checks.push('Unexpected JSON is rejected instead of being saved as an Excel file.');
 mode='delay';await start();before=report.queries.length;await dialog().getByRole('button',{name:'Download',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#obl-export-form [type=submit]').disabled);await page.evaluate(()=>document.querySelector('#obl-export-form').requestSubmit());await page.waitForTimeout(100);assert.equal(report.queries.length,before+1);before=report.downloads.length;await page.keyboard.press('Escape');release();await page.waitForTimeout(150);assert.equal(report.downloads.length,before);report.checks.push('Progress disables duplicate submissions; closing the dialog cancels a late download.');
 mode='ok';for(const width of [320,375,768,1440]){await page.setViewportSize({width,height:1000});for(const view of ['register','applicability','accountability']){await open('obligations'+(view==='register'?'':'?view='+view));await start();assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));assert(await dialog().evaluate(n=>n.scrollWidth<=n.clientWidth+1));if(width===375&&view==='register')await page.screenshot({path:path.join(out,'export-phone.png')});await page.keyboard.press('Escape');}}report.checks.push('Export controls and dialog fit all three tabs at 320, 375, 768 and 1440px.');
 identity={...original,roles:['BUSINESS_OWNER']};await open('obligations');assert.equal(await page.locator('[data-action=obl-export]').count(),0);await open('obligations?view=accountability');assert.equal(await page.locator('[data-action=obl-export]').count(),0);identity=original;report.checks.push('Read-only ownership roles do not receive export controls. Server-side denials are tested separately.');
 await open('obligations');await start();mode='expired';before=report.downloads.length;await dialog().getByRole('button',{name:'Download',exact:true}).click();await page.locator('#login').waitFor();assert.equal(await dialog().evaluate(n=>n.open),false);assert.equal(await page.locator('[data-action=obl-export]').count(),0);assert.equal(report.downloads.length,before);report.checks.push('Session expiry clears authenticated state, closes Export, returns to sign-in and downloads nothing.');
 assert.deepEqual(report.errors,[]);assert.deepEqual(report.writes,[]);assert.deepEqual(report.external_requests,[]);report.status='passed';
 }catch(error){report.status='failed';report.error=error.stack;process.exitCode=1;}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));await fs.writeFile(path.join(out,'validation.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:report.status,checks:report.checks.length,error:report.error}));}
})();
